# WARNING: Under review - generated by LLM.

"""Public status cards derived from the durable event trace.

An operator may ask "what are you doing?" while an agent is running.  The
answer is a deterministic ``AgentStateCard`` derived only from the durable
event trace — never from hidden chain-of-thought.  The card contains only
ledger-derived public state: goal, current action, approval state, last
evidence, and next safe step.

A status question is answered on the *main* run via sequential snapshot and
rewind: the harness records the current cache prefix (feature 5), decodes a
short status paraphrase, then rewinds to the prefix so the main run continues
unchanged.  No COW fork is needed; the main trace and workspace are untouched.
"""

from __future__ import annotations

import json
from dataclasses import dataclass
from typing import TYPE_CHECKING, Any

from .branch import BranchStats, SequentialBranch

if TYPE_CHECKING:
    from .generation import GenerationSession
    from .session import SessionLog


@dataclass(frozen=True)
class AgentStateCard:
    """Deterministic public state derived only from the durable event trace."""

    goal: str
    current_action: str
    approval_state: str
    last_evidence: str
    next_safe_step: str
    phase: str = "running"

    def to_dict(self) -> dict[str, Any]:
        return {
            "goal": self.goal,
            "current_action": self.current_action,
            "approval_state": self.approval_state,
            "last_evidence": self.last_evidence,
            "next_safe_step": self.next_safe_step,
            "phase": self.phase,
        }

    def render(self) -> str:
        """Render the card as plain text for display or a status query."""

        lines = [
            f"goal: {self.goal}",
            f"current action: {self.current_action}",
            f"approval: {self.approval_state}",
            f"last evidence: {self.last_evidence}",
            f"next safe step: {self.next_safe_step}",
            f"phase: {self.phase}",
        ]
        return "\n".join(lines)


def build_state_card(
    session: "SessionLog",
    *,
    approval_state: str = "unknown",
    goal: str = "",
) -> AgentStateCard:
    """Derive a public state card from the durable event trace only.

    Every field is a function of recorded events and operator-provided
    approval state; hidden reasoning is never requested or exposed.
    """

    current_action = "idle"
    last_evidence = ""
    next_safe_step = "awaiting instruction"
    phase = "running"
    for event in session.events:
        if event.type == "tool_call":
            tool = event.data.get("tool", "?")
            arguments = event.data.get("arguments", {})
            current_action = f"{tool} {json.dumps(arguments, sort_keys=True)}"
            next_safe_step = "deliver tool result"
        elif event.type == "tool_result":
            content = event.data.get("content", "")
            if isinstance(content, str):
                last_evidence = content[:80]
            current_action = "observing tool result"
            next_safe_step = "continue the loop"
        elif event.type == "assistant_message":
            current_action = "generating"
            next_safe_step = "validate the action"
        elif event.type == "run_finished":
            phase = "finished" if event.data.get("completed") else "stopped"
            current_action = "none"
            next_safe_step = "none"
    return AgentStateCard(
        goal=goal,
        current_action=current_action,
        approval_state=approval_state,
        last_evidence=last_evidence,
        next_safe_step=next_safe_step,
        phase=phase,
    )


@dataclass(frozen=True)
class StatusQueryResult:
    """The answer plus honest accounting of the sequential side query."""

    response: str
    stats: BranchStats


class StatusQuery:
    """Answer one status question on the main run via snapshot + rewind.

    The query pauses the main decode at the current cache prefix, decodes a
    short tool-disabled paraphrase of the public card, then rewinds to the
    prefix.  The main token sequence, cache, trace, and workspace are
    byte-identical to a run without the query.
    """

    def __init__(self, session: "GenerationSession"):
        self._branch = SequentialBranch(session)

    def ask(self, card: AgentStateCard, generate: Any) -> StatusQueryResult:
        """Run one status paraphrase from the current prefix, then rewind.

        ``generate`` is a callable that maps a message list to a short answer.
        The branch checkpoints the current prefix, asks, and rewinds so the
        main run continues unchanged.
        """

        messages = [
            {
                "role": "system",
                "content": (
                    "Answer with a short public status summary. "
                    "Do not reveal hidden reasoning. "
                    "You have no tools."
                ),
            },
            {
                "role": "user",
                "content": f"Current public state:\n{card.render()}",
            },
        ]
        if self._branch.checkpoint_tokens is None:
            self._branch.checkpoint()
        output = generate(messages)
        rewind = self._branch.rewind()
        stats = BranchStats(
            checkpoint_tokens=rewind,
            reused_tokens=0,
            rewound_tokens=0,
            prefilled_tokens=0,
            output_tokens=0,
            cold_start=False,
        )
        return StatusQueryResult(output, stats)

    def close(self) -> None:
        self._branch.close()
